sp_widget.css:
/* =========================================
   CFMS STAFF HOME
   ========================================= */

.cfms-staff-page {
    min-height: 100vh;

    background: #f0fbfc;

    color: #263238;

    font-family:
        "Segoe UI",
        Tahoma,
        Geneva,
        Verdana,
        sans-serif;
}


/* HEADER */

.staff-header {
    height: 72px;

    background: #00acc1;

    color: white;

    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 0 35px;

    box-sizing: border-box;
}


.staff-brand {
    display: flex;

    align-items: center;

    gap: 12px;
}


.brand-icon {
    width: 43px;
    height: 43px;

    border-radius: 9px;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;
}


.staff-brand h2 {
    margin: 0;

    font-size: 23px;
}


.staff-brand span {
    font-size: 11px;

    opacity: .9;
}


/* USER */

.staff-user {
    display: flex;

    align-items: center;

    gap: 10px;
}


.user-avatar {
    width: 38px;
    height: 38px;

    border-radius: 50%;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;
}


.user-info {
    display: flex;

    flex-direction: column;
}


.user-info strong {
    font-size: 14px;
}


.user-info span {
    font-size: 11px;

    opacity: .85;
}


.logout-btn {
    margin-left: 15px;

    padding: 8px 13px;

    border: 1px solid rgba(255,255,255,.7);

    background: transparent;

    color: white;

    border-radius: 6px;

    cursor: pointer;
}


.logout-btn:hover {
    background: white;

    color: #00acc1;
}


/* LAYOUT */

.staff-layout {
    display: flex;

    min-height: calc(100vh - 72px);
}


/* SIDEBAR */

.staff-sidebar {
    width: 235px;

    flex-shrink: 0;

    background: white;

    border-right: 1px solid #dceff1;

    padding: 25px 15px;

    box-sizing: border-box;
}


.sidebar-title {
    padding: 0 12px 15px;

    color: #78909c;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1px;
}


.sidebar-item {
    display: flex;

    align-items: center;

    gap: 13px;

    padding: 13px 14px;

    margin-bottom: 5px;

    border-radius: 8px;

    color: #546e7a !important;

    text-decoration: none !important;

    cursor: pointer;

    position: relative;
}


.sidebar-item:hover,
.sidebar-item.active {
    background: #e0f7fa;

    color: #00acc1 !important;
}


.sidebar-item i {
    width: 20px;

    text-align: center;
}


.menu-count {
    margin-left: auto;

    min-width: 20px;

    height: 20px;

    padding: 0 5px;

    box-sizing: border-box;

    border-radius: 10px;

    background: #00acc1;

    color: white;

    font-size: 10px;

    display: flex;

    align-items: center;

    justify-content: center;
}


.sidebar-divider {
    height: 1px;

    background: #e5eeee;

    margin: 20px 10px;
}


/* MAIN */

.staff-content {
    flex: 1;

    padding: 35px 45px;

    max-width: 1400px;

    box-sizing: border-box;
}


/* WELCOME */

.welcome-section {
    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 30px;
}


.page-label {
    color: #00acc1;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1px;
}


.welcome-section h1 {
    margin: 7px 0;

    font-size: 31px;
}


.welcome-section p {
    margin: 0;

    color: #607d8b;

    font-size: 14px;
}


.tickets-btn {
    padding: 13px 20px;

    background: #00acc1;

    border: none;

    border-radius: 8px;

    color: white;

    font-weight: 600;

    cursor: pointer;
}


.tickets-btn:hover {
    background: #008fa1;
}


/* STATS */

.stats-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 18px;

    margin-bottom: 35px;
}


.stat-card {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 12px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 15px;

    box-shadow:
        0 3px 15px rgba(0,0,0,.05);
}


.stat-icon {
    width: 50px;
    height: 50px;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 21px;
}


.stat-icon.teal {
    background: #e0f7fa;
    color: #00acc1;
}


.stat-icon.orange {
    background: #fff3e0;
    color: #fb8c00;
}


.stat-icon.blue {
    background: #e3f2fd;
    color: #1976d2;
}


.stat-icon.green {
    background: #e8f5e9;
    color: #43a047;
}


.stat-card span {
    display: block;

    color: #78909c;

    font-size: 12px;
}


.stat-card strong {
    display: block;

    margin-top: 3px;

    font-size: 25px;
}


/* SECTIONS */

.dashboard-section {
    margin-bottom: 35px;
}


.section-heading {
    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 18px;
}


.section-heading h2 {
    margin: 0 0 5px;

    font-size: 21px;
}


.section-heading p {
    margin: 0;

    color: #78909c;

    font-size: 13px;
}


/* ACTIONS */

.action-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 18px;
}


.action-card {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 13px;

    padding: 24px;

    cursor: pointer;

    transition: .25s ease;
}


.action-card:hover {
    transform: translateY(-5px);

    box-shadow:
        0 10px 25px rgba(0,0,0,.08);

    border-color: #b2ebf2;
}


.action-icon {
    width: 48px;
    height: 48px;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 15px;

    font-size: 20px;
}


.teal-bg {
    background: #e0f7fa;
    color: #00acc1;
}


.blue-bg {
    background: #e3f2fd;
    color: #1976d2;
}


.green-bg {
    background: #e8f5e9;
    color: #43a047;
}


.red-bg {
    background: #ffebee;
    color: #e53935;
}


.action-card h3 {
    margin: 0 0 8px;

    font-size: 17px;
}


.action-card p {
    min-height: 42px;

    margin: 0 0 15px;

    color: #607d8b;

    font-size: 13px;

    line-height: 1.6;
}


.action-card span {
    color: #00acc1;

    font-size: 12px;

    font-weight: 600;
}


/* PRIORITY */

.priority-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 15px;
}


.priority-card {
    background: white;

    border-radius: 10px;

    padding: 17px;

    display: flex;

    align-items: center;

    gap: 13px;

    border-left: 4px solid;
}


.priority-card.critical {
    border-left-color: #e53935;
}


.priority-card.high {
    border-left-color: #fb8c00;
}


.priority-card.medium {
    border-left-color: #f9a825;
}


.priority-card.low {
    border-left-color: #43a047;
}


.priority-number {
    font-size: 25px;

    font-weight: 700;
}


.priority-card strong {
    display: block;

    font-size: 13px;
}


.priority-card span {
    display: block;

    margin-top: 3px;

    color: #78909c;

    font-size: 10px;
}


/* TICKETS */

.view-all-btn {
    background: transparent;

    border: none;

    color: #00acc1;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;
}


.ticket-list {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 13px;

    overflow: hidden;
}


.ticket-row {
    min-height: 65px;

    padding: 12px 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    border-bottom: 1px solid #edf3f4;
}


.ticket-row:last-child {
    border-bottom: none;
}


.ticket-icon {
    width: 40px;
    height: 40px;

    border-radius: 8px;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;
}


.ticket-info {
    flex: 1;

    display: flex;

    flex-direction: column;

    gap: 3px;

    min-width: 0;
}


.ticket-info strong {
    color: #00acc1;

    font-size: 13px;
}


.ticket-info span {
    color: #607d8b;

    font-size: 12px;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


/* BADGES */

.status-badge,
.priority-badge {
    padding: 5px 9px;

    border-radius: 15px;

    font-size: 10px;

    font-weight: 600;

    white-space: nowrap;
}


.status-active {
    background: #fff8e1;

    color: #f57f17;
}


.status-progress {
    background: #e3f2fd;

    color: #1976d2;
}


.status-resolved {
    background: #e8f5e9;

    color: #2e7d32;
}


.priority-critical {
    background: #ffebee;

    color: #c62828;
}


.priority-high {
    background: #fff3e0;

    color: #ef6c00;
}


.priority-medium {
    background: #fff8e1;

    color: #f9a825;
}


.priority-low {
    background: #e8f5e9;

    color: #388e3c;
}


/* EMPTY */

.empty-state {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 13px;

    padding: 45px 20px;

    text-align: center;
}


.empty-icon {
    width: 60px;
    height: 60px;

    margin: 0 auto 15px;

    border-radius: 50%;

    background: #e8f5e9;

    color: #43a047;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;
}


.empty-state h3 {
    margin: 0 0 7px;
}


.empty-state p {
    color: #78909c;

    font-size: 13px;
}


/* RESPONSIVE */

@media (max-width: 1100px) {

    .stats-grid,
    .action-grid,
    .priority-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

}


@media (max-width: 800px) {

    .staff-sidebar {
        width: 70px;

        padding: 20px 8px;
    }

    .sidebar-title,
    .sidebar-item span {
        display: none;
    }

    .sidebar-item {
        justify-content: center;
    }

    .staff-content {
        padding: 25px;
    }

}


@media (max-width: 600px) {

    .staff-header {
        padding: 15px 18px;
    }

    .staff-brand span,
    .user-info {
        display: none;
    }

    .welcome-section {
        flex-direction: column;

        align-items: flex-start;

        gap: 18px;
    }

    .tickets-btn {
        width: 100%;
    }

    .stats-grid,
    .action-grid,
    .priority-grid {
        grid-template-columns: 1fr;
    }

    .ticket-row {
        flex-wrap: wrap;
    }

    .staff-content {
        padding: 20px 15px;
    }

}

sp_widget.script:
(function() {

    /* =========================================
       DEFAULT DATA
       ========================================= */

    data.userName = gs.getUserDisplayName();

    data.assignedCount = 0;

    data.openCount = 0;

    data.inProgressCount = 0;

    data.resolvedCount = 0;

    data.criticalCount = 0;

    data.highCount = 0;

    data.mediumCount = 0;

    data.lowCount = 0;

    data.recentTickets = [];

    data.error = "";


    /* =========================================
       LOGIN CHECK
       ========================================= */

    if (!gs.isLoggedIn()) {

        data.redirect = "cfms_login";

        return;
    }


    /* =========================================
       STAFF ROLE CHECK
       ========================================= */

    if (!gs.hasRole("cfms_staff") &&
        !gs.hasRole("admin")) {

        data.redirect = "cfms_home";

        return;
    }


    /* =========================================
       GET ASSIGNED TICKETS
       ========================================= */

    var gr =
        new GlideRecord("incident");


    /*
     * Assigned directly to current staff
     */

    var assignedQuery =
        gr.addQuery(
            "assigned_to",
            gs.getUserID()
        );


    gr.orderByDesc("sys_updated_on");

    gr.query();


    while (gr.next()) {

        data.assignedCount++;


        /* =====================================
           STATE
           ===================================== */

        var state =
            gr.getValue("state");

        var stateText =
            gr.getDisplayValue("state");


        if (state == "1") {

            data.openCount++;

        }

        else if (state == "2") {

            data.inProgressCount++;

        }

        else if (state == "6" ||
                 state == "7") {

            data.resolvedCount++;

        }

        else {

            data.openCount++;

        }


        /* =====================================
           PRIORITY
           ===================================== */

        var priority =
            gr.getValue("priority");

        var priorityText =
            gr.getDisplayValue("priority");

        var priorityClass =
            "priority-medium";


        if (priority == "1") {

            data.criticalCount++;

            priorityText = "Critical";

            priorityClass =
                "priority-critical";

        }

        else if (priority == "2") {

            data.highCount++;

            priorityText = "High";

            priorityClass =
                "priority-high";

        }

        else if (priority == "3") {

            data.mediumCount++;

            priorityText = "Medium";

            priorityClass =
                "priority-medium";

        }

        else if (priority == "4") {

            data.lowCount++;

            priorityText = "Low";

            priorityClass =
                "priority-low";

        }


        /* =====================================
           STATUS CLASS
           ===================================== */

        var statusClass =
            "status-active";


        if (state == "2") {

            statusClass =
                "status-progress";

        }

        else if (state == "6" ||
                 state == "7") {

            statusClass =
                "status-resolved";

        }


        /* =====================================
           RECENT 5
           ===================================== */

        if (data.recentTickets.length < 5) {

            data.recentTickets.push({

                sys_id:
                    gr.getUniqueValue(),

                number:
                    gr.getValue("number"),

                short_description:
                    gr.getValue(
                        "short_description"
                    ),

                state:
                    stateText,

                stateValue:
                    state,

                statusClass:
                    statusClass,

                priority:
                    priorityText,

                priorityValue:
                    priority,

                priorityClass:
                    priorityClass

            });

        }

    }


})();
